<?php require __DIR__.'/bootstrap.php';require __DIR__.'/mailer.php';$sent=false;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=strtolower(trim($_POST['email']??''));$ip=client_ip();$limit=$pdo->prepare('SELECT COUNT(*) FROM password_reset_requests WHERE (email=? OR request_ip=?) AND created_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$limit->execute([$email,$ip]);if((int)$limit->fetchColumn()<5){$u=$pdo->prepare("SELECT id,name,email FROM users WHERE email=? AND status='active' LIMIT 1");$u->execute([$email]);$user=$u->fetch();if($user){$token=bin2hex(random_bytes(32));$pdo->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$user['id']]);$pdo->prepare('INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 60 MINUTE))')->execute([$user['id'],hash('sha256',$token)]);$pdo->prepare('INSERT INTO password_reset_requests(email,request_ip) VALUES(?,?)')->execute([$email,$ip]);try{$link='https://newsiga.com.br'.url('redefinir-senha.php?token='.$token);send_portal_mail($user['email'],$user['name'],'Redefinição de senha | Newsiga',recovery_email($user['name'],$link));audit('password_reset_requested','user',(int)$user['id']);}catch(Throwable $ex){error_log('Newsiga mail: '.$ex->getMessage());$error='Não foi possível enviar o e-mail neste momento. Tente novamente mais tarde.';}}}$sent=$error==='';}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Recuperar acesso | Newsiga</title><link rel="stylesheet" href="assets/style.css"></head><body class="login-bg"><main class="login-card"><a class="brand" href="/">newsiga</a><p class="kicker">RECUPERAR ACESSO</p><h1>Esqueceu sua senha?</h1><?php if($sent):?><p class="success">Se o e-mail estiver cadastrado, você receberá um link válido por 60 minutos.</p><a class="button secondary-link" href="<?=url()?>">Voltar ao login</a><?php else:?><p>Informe seu e-mail para receber um link seguro.</p><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>E-mail corporativo<input name="email" type="email" required autocomplete="email"></label><button class="button">Enviar link</button></form><a class="login-help" href="<?=url()?>">Voltar ao login</a><?php endif;?></main></body></html>
